convergences=[
 dict(date="1720-10",label="October 1720: the embassy sails while Paris hopes to stop it",eyes=["mehmed","sutton","penterriedter","dirling"],note="On 7 October Mehmed embarked in Istanbul; within a week the British and Habsburg envoys in Paris were reporting that Dubois wanted him halted at Toulon, while in Istanbul Dirling was paying an informant to learn what the mission was for. The traveller set out without knowing how unwanted he was."),
 dict(date="1720-11-22",label="November 1720: landing at Toulon in a plague year",eyes=["mehmed","dubois","bernage","roquelaure"],note="Dubois's letter of 4 November still hoped the embassy would not come; Bernage was ordering its cotton burned; Roquelaure had already chosen an island for a second quarantine. Mehmed, saluted by cannon and kept aboard, saw honour and confinement at once."),
 dict(date="1720-12-17",label="December 1720: Sète and the island of Maguelone",eyes=["mehmed","roquelaure"],note="Roquelaure counted the stragglers who had joined the embassy and noted the arrival of its escort; Mehmed, in a ruined church on a lagoon island, wrote of exile and patience. One record is logistics, the other a state of mind."),
 dict(date="1721-01-24",label="Late January 1721: end of quarantine and the canal",eyes=["bernage","dubois","mehmed"],note="Bernage chose sweetmeats over wine and Dubois worried about costs, while Mehmed boarded the canal boats and admired Riquet's engineering. The hosts' concern was the bill; the guest's was the works."),
 dict(date="1721-03-16",label="16–21 March 1721: the entry and the royal audience",eyes=["mehmed","mercure","penterriedter"],note="The Mercure saw costumes and horse-tail standards; Pentenriedter saw a capable man with possibly hidden aims; Mehmed recorded the ceremonial he had negotiated and the boy king he met. Three gazes on the same procession: spectacle, suspicion and protocol."),
 dict(date="1721-04-25",label="Late April–May 1721: Vienna watches",eyes=["penterriedter","wiener-diarium","sutton"],note="After Mehmed's return call on 25 April, Pentenriedter reported his hints; the Vienna newspaper printed a Paris rumour about Ottoman war aims; Sutton followed the same story from the British embassy. The visitor had become an object of rival intelligence."),
 dict(date="1721-06-07",label="June 1721: Versailles and the Malta question",eyes=["mehmed","sutton"],note="While Mehmed spent five days among the mirrors and fountains of Versailles, Sutton was reporting his unsuccessful talks with Dubois about Ottoman captives in Malta. The traveller's report keeps the wonders; the diplomats keep the failure."),
 dict(date="1721-08",label="August 1721: departure",eyes=["mehmed","penterriedter","mercure","michon"],note="As the embassy left Paris, Pentenriedter filed his account of Dubois's refusal over Malta and the Mercure praised the envoy's European taste; in Lyon, Michon noted his tour of the city."),
 dict(date="1721-10",label="October–November 1721: the return and its echoes in Istanbul",eyes=["mehmed","dirling","stanyan"],note="Mehmed came home on 8 October to write his report; within weeks Dirling and Stanyan were passing on what he said, and what he was afraid to say, about France."),
]

